-- Knowledge: the approved facts agents may quote ----------------------------
delete from public.knowledge_chunks
where tenant_id = (select id from public.tenants where slug = 'alcadent')
  and metadata ->> 'managed_by' = 'onboarding';

insert into public.knowledge_chunks (tenant_id, source, title, content, metadata)
values
  ((select id from public.tenants where slug = 'alcadent'), 'clinic_facts', 'Opening hours', 'Alcadent India is open seven days a week. Monday to Saturday 10:00 to 20:00, Sunday 11:00 to 17:00. Walk-ins are accepted but an appointment is faster.', '{"managed_by":"onboarding","approved_by":"clinic"}'::jsonb),
  ((select id from public.tenants where slug = 'alcadent'), 'clinic_facts', 'Location and parking', 'F-49, First Floor, Elan Miracle Mall, Sector 84, Gurugram 122004. Parking is available in the mall basement. The clinic is on the first floor, near the atrium lifts.', '{"managed_by":"onboarding","approved_by":"clinic"}'::jsonb),
  ((select id from public.tenants where slug = 'alcadent'), 'clinic_facts', 'Anxious children', 'The clinic uses a painless injection technique and offers conscious sedation for children who are very anxious. Parents can stay with the child during the visit. A first visit is usually a short, friendly familiarisation appointment.', '{"managed_by":"onboarding","approved_by":"clinic"}'::jsonb),
  ((select id from public.tenants where slug = 'alcadent'), 'oral_hygiene', 'Brushing for children', 'Children should brush twice a day with a pea-sized amount of fluoride toothpaste, with adult supervision until about age seven. Replace the brush every three months. Limit sugary drinks between meals.', '{"managed_by":"onboarding","approved_by":"clinic"}'::jsonb);

